<script lang="ts">import {getContext} from 'svelte';import type {I18nState} from '../../../../../lib/i18n/i18n.svelte';import {createRefundsState} from '../state/refundsState.svelte';const i18n=getContext<I18nState>('i18n');const vm=createRefundsState();$effect(()=>{const s=vm.status,q=vm.search;void vm.load();});</script>
<section class="page"><header><div><p class="eyebrow">ABELLIS · SMART WMS</p><h1>{i18n.t('Reembolsos')}</h1><p>{i18n.t('Registro de notas de crédito emitidas por el POS. Esta pantalla es de consulta; el reembolso se ejecuta en el flujo de pago.')}</p></div><button onclick={()=>void vm.load()}>{i18n.t('Actualizar')}</button></header><div class="filters"><select value={vm.status} onchange={e=>{vm.setStatus(e.currentTarget.value);void vm.load();}}><option value="">{i18n.t('Todos los estados')}</option><option value="SHIPPED">SHIPPED</option><option value="CANCELLED">CANCELLED</option></select><input placeholder={i18n.t('Buscar por número de reembolso')} value={vm.search} oninput={e=>vm.setSearch(e.currentTarget.value)} onkeydown={e=>{if(e.key==='Enter')void vm.load();}}/><button onclick={()=>void vm.load()}>{i18n.t('Buscar')}</button></div>{#if vm.error}<p class="error" role="alert">{vm.error}</p>{/if}
{#if vm.loading}<p>{i18n.t('Cargando…')}</p>{:else}<div class="table-wrap"><table><thead><tr><th>{i18n.t('Reembolso')}</th><th>{i18n.t('Cliente')}</th><th>{i18n.t('Estado')}</th><th>{i18n.t('Fecha')}</th><th>{i18n.t('Importe')}</th></tr></thead><tbody>{#each vm.rows as r (r.salesOrderId)}<tr onclick={()=>void vm.detail(r.salesOrderId)}><td><button class="link" onclick={e=>{e.stopPropagation();void vm.detail(r.salesOrderId);}}>{r.salesOrderNumber}</button></td><td>{r.customerName??'—'}</td><td>{r.status}</td><td>{r.createdAt??'—'}</td><td>{new Intl.NumberFormat(undefined,{style:'currency',currency:'USD'}).format(r.orderTotal)}</td></tr>{/each}</tbody></table></div>{/if}
{#if vm.selected}<aside class="detail"><header><div><h2>{vm.selected.salesOrderNumber}</h2><p>{vm.selected.status} · {vm.selected.customerName??'—'}</p></div><button onclick={()=>vm.close()}>{i18n.t('Cerrar')}</button></header><p>{i18n.t('Pedido original')}: {vm.selected.parentSalesOrderId??'—'}</p><h3>{i18n.t('Líneas reembolsadas')}</h3><table><thead><tr><th>SKU</th><th>{i18n.t('Producto')}</th><th>{i18n.t('Cantidad')}</th></tr></thead><tbody>{#each vm.selected.lines as l (l.soLineId)}<tr><td>{l.sku??'—'}</td><td>{l.itemName??l.itemId}</td><td>{l.quantityOrdered}</td></tr>{/each}</tbody></table></aside>{/if}</section>
<style>.page{max-width:78rem;margin:1.4rem auto;padding:0 1.1rem;color:var(--ink)}header{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-bottom:1rem}h1{margin:0;font:700 1.6rem var(--disp)}header p,.detail p{color:var(--slate);font-size:.9rem}.eyebrow{font:600 .65rem var(--disp);letter-spacing:.14em}button{border:1px solid var(--line);border-radius:8px;padding:.5rem .7rem;background:var(--card);color:var(--ink);cursor:pointer}.filters{display:flex;gap:.6rem;margin:1rem 0}.filters input,.filters select{min-height:38px;border:1px solid var(--line);border-radius:8px;padding:.45rem;background:var(--card);color:var(--ink)}.filters input{flex:1}.table-wrap,.detail{overflow:auto;border:1px solid var(--line);border-radius:12px;background:var(--card);margin:1rem 0}.detail{padding:1rem}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:.82rem}th,td{text-align:left;padding:.65rem;border-bottom:1px solid var(--line)}th{color:var(--slate);font-size:.7rem;text-transform:uppercase}.link{border:0;background:none;color:var(--accent);text-decoration:underline}.error{color:var(--danger)}</style>